struct AD {double v=0,d[3]{},dd[3][3]{};AD(double x=0):v(x){};AD&operator+=(const AD&);AD&operator-=(const AD&);};
AD operator+(AD a,const AD&b){a.v+=b.v;for(int i=0;i<3;++i){a.d[i]+=b.d[i];for(int j=0;j<3;++j)a.dd[i][j]+=b.dd[i][j];}return a;}
AD operator-(AD a){a.v=-a.v;for(int i=0;i<3;++i){a.d[i]=-a.d[i];for(int j=0;j<3;++j)a.dd[i][j]=-a.dd[i][j];}return a;}
AD operator-(AD a,const AD&b){return a+(-b);}AD&AD::operator+=(const AD&b){return *this=*this+b;}AD&AD::operator-=(const AD&b){return *this=*this-b;}
AD operator*(const AD&a,const AD&b){AD r(a.v*b.v);for(int i=0;i<3;++i){r.d[i]=a.d[i]*b.v+a.v*b.d[i];for(int j=0;j<3;++j)r.dd[i][j]=a.dd[i][j]*b.v+a.d[i]*b.d[j]+a.d[j]*b.d[i]+a.v*b.dd[i][j];}return r;}
AD inverse(const AD&a){AD r(1/a.v);for(int i=0;i<3;++i){r.d[i]=-a.d[i]/(a.v*a.v);for(int j=0;j<3;++j)r.dd[i][j]=2*a.d[i]*a.d[j]/(a.v*a.v*a.v)-a.dd[i][j]/(a.v*a.v);}return r;}
AD operator/(const AD&a,const AD&b){return a*inverse(b);}bool operator>(const AD&a,const AD&b){return a.v>b.v;}AD expAD(const AD&a){AD r(std::exp(a.v));for(int i=0;i<3;++i){r.d[i]=r.v*a.d[i];for(int j=0;j<3;++j)r.dd[i][j]=r.v*(a.dd[i][j]+a.d[i]*a.d[j]);}return r;}
AD powAD(const AD&a,const AD&e){for(int i=0;i<3;++i){if(e.d[i]!=0)throw std::runtime_error("dynamic AD exponent unsupported");for(int j=0;j<3;++j)if(e.dd[i][j]!=0)throw std::runtime_error("dynamic AD exponent unsupported");}AD r(std::pow(a.v,e.v));double f=e.v*std::pow(a.v,e.v-1),ff=e.v*(e.v-1)*std::pow(a.v,e.v-2);for(int i=0;i<3;++i){r.d[i]=f*a.d[i];for(int j=0;j<3;++j)r.dd[i][j]=f*a.dd[i][j]+ff*a.d[i]*a.d[j];}return r;}
namespace Kokkos {inline AD pow(const AD&a,const AD&e){return powAD(a,e);}inline AD sqrt(const AD&a){return powAD(a,AD(.5));}}
namespace Kokkos {inline bool isfinite(const AD&a){bool ok=std::isfinite(a.v);for(int i=0;i<3;++i){ok=ok&&std::isfinite(a.d[i]);for(int j=0;j<3;++j)ok=ok&&std::isfinite(a.dd[i][j]);}return ok;}}
