AD partialPolynomial(const AD&a,int i){AD r(a.d[i]);for(int j=0;j<3;++j)r.d[j]=a.dd[i][j];return r;}
void scalar(h::ScalarJet<AD>&s,const AD&a){s.value=a;for(int i=0;i<3;++i){s.d[i]=partialPolynomial(a,i);for(int j=0;j<3;++j)s.dd[i][j]=AD(a.dd[i][j]);}}
template<class T>std::vector<T*> entries(h::Z4cJet<T>&u){std::vector<T*>r;for(int i=0;i<3;++i)for(int j=0;j<3;++j){r.push_back(&u.metric.g[i][j]);r.push_back(&u.a.k[i][j]);for(int k=0;k<3;++k){r.push_back(&u.metric.dg[k][i][j]);r.push_back(&u.a.dk[k][i][j]);for(int l=0;l<3;++l)r.push_back(&u.metric.ddg[k][l][i][j]);}}
 for(auto*s:{&u.chi,&u.alpha,&u.trace,&u.theta}){r.push_back(&s->value);for(int i=0;i<3;++i){r.push_back(&s->d[i]);for(int j=0;j<3;++j)r.push_back(&s->dd[i][j]);}}
 for(auto*s:{&u.beta,&u.lambda})for(int i=0;i<3;++i){r.push_back(&s->value[i]);for(int j=0;j<3;++j){r.push_back(&s->d[j][i]);for(int k=0;k<3;++k)r.push_back(&s->dd[j][k][i]);}}return r;}
void scalarRHS(h::ScalarJet<double>&s,const AD&a){s.value=a.v;for(int i=0;i<3;++i){s.d[i]=a.d[i];for(int j=0;j<3;++j)s.dd[i][j]=a.dd[i][j];}}

void radialScalar(h::ScalarJet<AD>&s,h::Radial2<AD>v){s={};s.value=v.value;s.d[0]=v.d;s.dd[0][0]=v.dd;}
h::Z4cJet<AD> OuterMassive(AD x[3],double mass){AD r=Kokkos::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]),n[3]={x[0]/r,x[1]/r,x[2]/r};using R=h::Radial2<AD>;R one{1,0,0},rr{r,1,0},om{(1-r*r)/2,-r,-1},mh{mass/2,0,0},invpsi=rr/(rr+mh*om),lp=(rr-mh*om)/(rr+mh*om),ip2=invpsi*invpsi,m=mh*om/rr,den=one-m*m,ar{(1+r*r)/2,r,1},br{-r,-1,0};auto kr=R{-1,0,0}*ip2*(one+R{2,0,0}*m/den),kt=R{-1,0,0}*ip2*lp,shear=R{-1,0,0}*ip2*R{mass,0,0}*(R{2,0,0}-m)/(rr*den);h::Z4cJet<AD>a{};for(int i=0;i<3;++i)a.metric.g[i][i]=1;radialScalar(a.chi,ip2*ip2);radialScalar(a.alpha,ar*lp);radialScalar(a.trace,kr+R{2,0,0}*kt);auto bv=br*lp*ip2;a.beta.value[0]=bv.value;a.beta.d[0][0]=bv.d;a.beta.dd[0][0][0]=bv.dd;a.a.k[0][0]=AD(2./3.)*shear.value;a.a.dk[0][0][0]=AD(2./3.)*shear.d;for(int i=1;i<3;++i){a.a.k[i][i]=AD(-1./3.)*shear.value;a.a.dk[0][i][i]=AD(-1./3.)*shear.d;}return h::CartesianRadialJet(a,r,n);}
double Integrability(const h::Z4cJet<AD>&u){double err=0;auto check=[&](double a,double b){err=std::max(err,std::abs(a-b)/std::max(1.,std::max(std::abs(a),std::abs(b))));};for(const auto*f:{&u.chi,&u.alpha,&u.trace,&u.theta})for(int i=0;i<3;++i){check(f->value.d[i],f->d[i].v);for(int j=0;j<3;++j){check(f->value.dd[i][j],f->dd[i][j].v);check(f->d[i].d[j],f->dd[i][j].v);for(int k=0;k<3;++k)check(f->d[i].dd[j][k],f->dd[i][j].d[k]);}}for(int i=0;i<3;++i)for(int j=0;j<3;++j){check(u.a.k[i][j].d[0],u.a.dk[0][i][j].v);for(int d=0;d<3;++d){check(u.metric.g[i][j].d[d],u.metric.dg[d][i][j].v);for(int e=0;e<3;++e)check(u.metric.g[i][j].dd[d][e],u.metric.ddg[d][e][i][j].v);}}for(const auto*f:{&u.beta,&u.lambda})for(int c=0;c<3;++c)for(int i=0;i<3;++i){check(f->value[c].d[i],f->d[i][c].v);for(int j=0;j<3;++j){check(f->value[c].dd[i][j],f->dd[i][j][c].v);for(int k=0;k<3;++k)check(f->d[i][c].dd[j][k],f->dd[i][j][c].d[k]);}}return err;}
